// Data migrations: workspaces saved by 1.5.4–1.5.8 (generated by those builds) and a minimal 1.3-era one.
import { open, ok, done, waitInPage } from './lib.mjs';
import fs from 'fs';
const fx = ['1.5.4', '1.5.5', '1.5.6', '1.5.7', '1.5.8'].map(v => JSON.parse(fs.readFileSync(`fixtures/ws-${v}.json`, 'utf8')));
const tiny = { schema: 'crg-workspace/1', id: 'ws_old13', name: 'Very old', kind: 'organization', created: '2025-01-01', modified: '2025-01-02',
  org: { name: 'Old Co', regulations: 'Law 25; PIPEDA' }, assessment: { APPETITE: 0.3, FACTOR: 1000, SCEN: [] } };
const { browser, page, errors } = await open('#/process');
const r = await page.evaluate(async ({ fx, tiny }) => {
  const M = await import('/js/migrate.js'); const st = await import('/js/state.js'); const store = await import('/js/store.js');
  const crg = self.CRG; const out = {};
  // factory and known fields agree (a new field forces a new migration step)
  const nw = st.newWorkspace();
  out.unknownInFactory = Object.keys(nw).filter(k => !M.KNOWN_FIELDS.includes(k));
  out.factoryVersion = nw.dataVersion;
  const R = await import('/js/reset.js'); const g = new Set(); for (const x of Object.values(R.GROUPS)) for (const k of x) g.add(k);
  out.knownWithoutGroup = M.KNOWN_FIELDS.filter(k => !g.has(k) && k !== 'assessment');
  out.per = [];
  for (const f of [...fx, { app: '1.3 (hand-made)', workspaces: [tiny] }]) {
    for (const w of f.workspaces) {
      const before = JSON.parse(JSON.stringify(w));
      const res = M.migrateWorkspace(JSON.parse(JSON.stringify(w)), { fill: st.migrate });
      const m = res.ws;
      const missing = M.KNOWN_FIELDS.filter(k => !(k in m) && !['classroom'].includes(k));
      // numbers unchanged: engine totals equal before and after
      let same = true;
      if ((before.assessment?.SCEN || []).length) {
        const a = crg.run(before.assessment), b = crg.run(m.assessment);
        same = Math.round(a.totals.est) === Math.round(b.totals.est) && Math.round(a.totals.res) === Math.round(b.totals.res);
      }
      out.per.push({ app: f.app, name: w.name, status: res.status, to: m.dataVersion, missing, same, log: (m.migrationLog || []).length,
        incMoved: (before.incidents || []).length === (m.csm?.incidents || []).filter(x => x.source === 'imported').length && !('incidents' in m),
        exModel: !(m.isp?.issues || []).some(x => x.type === 'exception') && (m.shared?.exceptions || []).every(x => 'compensatedBy' in x && x.waivesLaw === false)
          && (m.shared?.exceptions || []).filter(x => !(x.concerns || []).some(l => l.kind === 'deviation')).length === [...(before.isp?.issues || []), ...(before.shared?.exceptions || [])].filter(x => x.type === 'exception').length,   // a teaching case also receives its identity, privilege & configuration sample exception (on a deviation)
        evMoved: !('evidence' in (m.grc || {})) && (m.shared?.evidence || []).length === (before.grc?.evidence || []).length,
        newRecords: ['cms', 'siem', 'soar', 'shared'].every(k => m[k] && typeof m[k] === 'object'),
        origUntouched: JSON.stringify(w) === JSON.stringify(before) });
    }
  }
  // idempotent: a migrated workspace is current
  const once = M.migrateWorkspace(JSON.parse(JSON.stringify(fx[3].workspaces[1])), { fill: st.migrate }).ws;
  out.second = M.migrateWorkspace(once, { fill: st.migrate }).status;
  // a newer workspace is not migrated and opens read-only
  const newer = { ...JSON.parse(JSON.stringify(once)), id: 'ws_future', name: 'From the future', dataVersion: M.DATA_VERSION + 1, futureField: 1 };
  out.newer = M.migrateWorkspace(newer).status;
  // a failing step leaves the original untouched
  const bad = JSON.parse(JSON.stringify(fx[0].workspaces[0])); bad.isp = { issues: 5 };
  const snap = JSON.stringify(bad);
  const fr = M.migrateWorkspace(bad, { fill: st.migrate });
  out.failed = { status: fr.status, untouched: JSON.stringify(bad) === snap, error: !!fr.error };
  // stored round trip: put a 1.5.6 workspace and the future one in the store, reload, check the outcome
  const w156 = JSON.parse(JSON.stringify(fx[2].workspaces.find(w => w.kind !== 'example'))); w156.id = 'ws_fx156';
  await store.put('ws', w156.id, w156); await store.put('ws', newer.id, newer);
  return out;
}, { fx, tiny });
ok(!r.unknownInFactory.length, 'every factory field is in KNOWN_FIELDS ' + r.unknownInFactory);
ok(r.factoryVersion === 5, 'new workspaces carry data version 5');
ok(!r.knownWithoutGroup.length, 'every known field belongs to a reset group ' + r.knownWithoutGroup);
for (const p of r.per) {
  ok(p.status === 'migrated' && p.to === 5, `${p.app} · ${p.name}: migrated to data version 5 (${p.status})`);
  ok(p.evMoved && p.newRecords, `${p.app} · ${p.name}: evidence moved to the shared register, new records present`);
  ok(!p.missing.length, `${p.app} · ${p.name}: every field present ${p.missing}`);
  ok(p.same, `${p.app} · ${p.name}: engine totals unchanged`);
  ok(p.log === 1 && p.incMoved && p.exModel && p.origUntouched, `${p.app} · ${p.name}: journalled, incidents moved, exceptions modelled, original untouched`);
}
ok(r.second === 'current', 'migrating twice changes nothing');
ok(r.newer === 'newer', 'a newer data version is not migrated');
ok(r.failed.status === 'failed' && r.failed.untouched && r.failed.error, 'a failing step leaves the original untouched and says why');
// reload: start-up migration, pre-migration copy, read-only for the future workspace
await page.reload();
await waitInPage(page, async () => { const m = await import('/js/state.js'); return !!m.S.ws; }, null, { timeout: 20000, every: 300 });
await page.waitForTimeout(1500);
const s2 = await page.evaluate(async () => {
  const st = await import('/js/state.js'); const store = await import('/js/store.js');
  const w = await store.get('ws', 'ws_fx156'); const pre = await store.get('blob', 'premig:ws_fx156');
  const fut = await store.get('ws', 'ws_future');
  await st.select('ws_future'); st.S.ws.name = 'changed'; st.touch(); await st.saveNow();
  const fut2 = await store.get('ws', 'ws_future');
  return { v: w.dataVersion, pre: !!pre && pre.ws.dataVersion === undefined, ro: st.isReadOnly(), futName: fut2.name, futField: fut2.futureField, migs: st.S.migrations.map(m => m.status + ':' + m.id + ':' + m.error), keys: Object.keys(w).length, dv: w.dataVersion, wid: w.id };
});
ok(s2.v === 5 && s2.pre, 'start-up migrates stored workspaces and keeps the copy from before');
ok(s2.ro && s2.futName === 'From the future' && s2.futField === 1, 'a newer workspace opens read-only and is never saved over');
await page.evaluate(() => { location.hash = '#/backup'; });
ok(await page.waitForSelector('#panel-backup >> text=Data versions and migrations', { timeout: 8000 }).then(() => true, () => false), 'Backup & restore explains data versions');
ok(await page.waitForSelector('#panel-backup .mig-banner', { timeout: 8000 }).then(() => true, () => false), 'read-only banner shown');
// clean up
await page.evaluate(async () => { const st = await import('/js/state.js'); await st.remove('ws_future'); await st.remove('ws_fx156'); });
ok(!errors.length, 'no console errors ' + errors.join(' | ').slice(0, 300));
await browser.close(); done('t11 migration');
